package org.apache.commons.math3.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math3.FieldElement;
import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.NullArgumentException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.MathUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_reciprocal_TriageGen5Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testReciprocal_NaN() {
        Complex c = Complex.NaN;
        Complex result = c.reciprocal();
        Assert.assertTrue("Result should be NaN", result.isNaN());
    }

    @Test
    public void testReciprocal_Zero() {
        Complex c = new Complex(0.0, 0.0);
        Complex result = c.reciprocal();
        Assert.assertTrue("Reciprocal of (0,0) should be NaN", result.isNaN());
    }

    @Test
    public void testReciprocal_Infinite() {
        // Test real infinite
        Complex c1 = new Complex(Double.POSITIVE_INFINITY, 0.0);
        Complex result1 = c1.reciprocal();
        Assert.assertEquals(Complex.ZERO, result1);

        // Test imaginary infinite
        Complex c2 = new Complex(0.0, Double.NEGATIVE_INFINITY);
        Complex result2 = c2.reciprocal();
        Assert.assertEquals(Complex.ZERO, result2);
    }

    @Test
    public void testReciprocal_RealDominant() {
        // Case where |real| >= |imaginary|
        // Using (2, 1) -> reciprocal is (2/5, -1/5) = (0.4, -0.2)
        Complex c = new Complex(2.0, 1.0);
        Complex result = c.reciprocal();

        Assert.assertEquals(0.4, result.getReal(), EPSILON);
        Assert.assertEquals(-0.2, result.getImaginary(), EPSILON);
    }

    @Test
    public void testReciprocal_ImaginaryDominant() {
        // Case where |real| < |imaginary|
        // Using (1, 2) -> reciprocal is (1/5, -2/5) = (0.2, -0.4)
        Complex c = new Complex(1.0, 2.0);
        Complex result = c.reciprocal();

        Assert.assertEquals(0.2, result.getReal(), EPSILON);
        Assert.assertEquals(-0.4, result.getImaginary(), EPSILON);
    }

    @Test
    public void testReciprocal_NegativeValues() {
        // Test negative values to ensure signs are handled correctly
        // ( -2, -1 ) -> reciprocal is (-2/5, 1/5) = (-0.4, 0.2)
        Complex c = new Complex(-2.0, -1.0);
        Complex result = c.reciprocal();

        Assert.assertEquals(-0.4, result.getReal(), EPSILON);
        Assert.assertEquals(0.2, result.getImaginary(), EPSILON);
    }

    @Test
    public void testReciprocal_EqualMagnitude() {
        // Testing the boundary |real| == |imaginary|
        // (1, 1) -> reciprocal is (0.5, -0.5)
        Complex c = new Complex(1.0, 1.0);
        Complex result = c.reciprocal();

        Assert.assertEquals(0.5, result.getReal(), EPSILON);
        Assert.assertEquals(-0.5, result.getImaginary(), EPSILON);
    }
}
